def norm(crop):
    res=set()
    g=[list(r) for r in crop]
    for flip in range(2):
        for rot in range(4):
            cur=g
            res.add(tuple(map(tuple,cur)))
            for r in range(rot):
                cur=[list(r) for r in zip(*cur[::-1])]
            g=[r[::-1] for r in g]
    return res
