def feats(cc,I):
    ys=[p[0] for p in cc];xs=[p[1] for p in cc]
    my=min(ys);mx=min(xs);MY=max(ys);MX=max(xs)
    crop=[[I[y][x] for x in range(mx,MX+1)] for y in range(my,MY+1)]
    hh=len(crop);ww=len(crop[0])
    ccount=sum(1 for y in range(hh) for x in range(ww) if crop[y][x]!=0)
    # bbox perimeter cells occupied
    perim=2*(hh+ww)-4
    bp=sum(1 for y in range(hh) for x in range(ww) if (y in(0,hh-1) or x in(0,ww-1)) and crop[y][x]!=0)
    # count bg cells on bbox edges
    bep=sum(1 for y in range(hh) for x in range(ww) if (y in(0,hh-1) or x in(0,ww-1)) and crop[y][x]==0)
    # interior bg count
    intbg=sum(1 for y in range(1,hh-1) for x in range(1,ww-1) if crop[y][x]==0)
    # longest straight run
    best=0
    for y in range(hh):
        x=0
        while x<ww:
            if crop[y][x]!=0:
                k=x
                while k+1<ww and crop[y][k+1]!=0: k+=1
                best=max(best,k-x+1); x=k+1
            else: x+=1
    for x in range(ww):
        y=0
        while y<hh:
            if crop[y][x]!=0:
                k=y
                while k+1<hh and crop[k+1][x]!=0: k+=1
                best=max(best,k-y+1); y=k+1
            else: y+=1
    return dict(sz=len(cc),h=hh,w=ww,fill=ccount/(hh*ww),bp=bp,bep=bep,intbg=intbg,long=best,
                 my=my,mx=mx,MY=MY,MX=MX)
