def bg_enclosed(crop, hh, ww):
    # bg cells inside bbox not reachable from bbox border through bg cells (4-conn)
    from collections import deque as dq
    reach=[[False]*ww for _ in range(hh)]
    bqd=dq()
    for x in range(ww):
        for y in (0,hh-1):
            if crop[y][x]!=col and not reach[y][x]: reach[y][x]=True; bqd.append((y,x))
    for y in range(hh):
        for x in (0,ww-1):
            if crop[y][x]!=col and not reach[y][x]: reach[y][x]=True; bqd.append((y,x))
    while bqd:
        y,x=bqd.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<hh and 0<=b<ww and crop[a][b]!=col and not reach[a][b]:
                reach[a][b]=True; bqd.append((a,b))
    return sum(1 for y in range(hh) for x in range(ww) if crop[y][x]!=col and not reach[y][x])
