def compstats(I,O=None):
    h=len(I);w=len(I[0])
    col=[x for x in set(sum(I,[0])) if x!=0][0]
    Cs=comps8(I,col)
    res=[]
    for cc in Cs:
        ys=[p[0] for p in cc];xs=[p[1] for p in cc]
        my,mx,MY,MX=min(ys),min(xs),max(ys),max(xs)
        hh,ww=MY-my+1, MX-mx+1
        crop=[[I[y][x] for x in range(mx,MX+1)] for y in range(my,MY+1)]
        pts={(a,b) for a in range(hh) for b in range(ww) if crop[a][b]==col}
        runsH=max(max(sum(1 for j in range(ww) if (i,j) in pts) for i in range(hh)),0)
        runsV=max(max(sum(1 for i in range(hh) if (i,j) in pts) for j in range(ww)),0)
        # holes inside bbox not reachable from outside via 4-connectivity
        seens=[[False]*ww for _ in range(hh)]; q=dq()
        for i in range(hh):
            for j in range(ww):
                if crop[i][j]==0 and (i in(0,hh-1) or j in(0,ww-1)):
                    seens[i][j]=True;q.append((i,j))
        while q:
            y,x=q.popleft()
            for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                a,b=y+dy,x+dx
                if 0<=a<hh and 0<=b<ww and crop[a][b]==0 and not seens[a][b]:
                    seens[a][b]=True;q.append((a,b))
        holes=sum(1 for i in range(hh) for j in range(ww) if crop[i][j]==0 and not seens[i][j])
        iswin = O is not None and crop==O
        res.append(dict(sz=len(cc),bh=hh,bw=ww,runsH=runsH,runsV=runsV,holes=holes,
                        nlineH=sum(1 for i in range(hh) if sum(1 for j in range(ww) if (i,j) in pts)>=2),
                        nlineV=sum(1 for j in range(ww) if sum(1 for i in range(hh) if (i,j) in pts)>=2),
                        t=(my,mx),iswin=iswin))
    return res
